// Generated by Damocles from the journey JSON beside it; PreviewJourney writes it again, so edits here are lost.
// It replays the design's journey against the real app: point SCREEN_URL at the page that implements the screen
// (or set DAMOCLES_JOURNEY_URL) and bring that page to the journey's STATE first. It finds controls by role and
// accessible name, so the real controls need the names the design gave them.
import { expect, test } from '@playwright/test';

const SCREEN_URL = process.env['DAMOCLES_JOURNEY_URL'] ?? '/';
const SCREEN = "S1";
const STATE = "default";
const UNTESTED: readonly string[] = ["Saving a contact", "Deleting a contact", "Search with no results"];

for (const width of [390, 1280]) {
  test(`${SCREEN} journey at ${width} px`, async ({ page }) => {
    test.info().annotations.push({ type: 'state', description: STATE }, ...UNTESTED.map((description) => ({ type: 'untested', description })));
    await page.setViewportSize({ width, height: 900 });
    await page.goto(SCREEN_URL);
    await page.getByPlaceholder("Search contacts", { exact: true }).fill("Grace");
    await expect(page.getByRole("list", { name: "Contacts", exact: true })).toContainText("Grace Hopper");
    await page.getByRole("button", { name: "Add contact", exact: true }).click();
    await expect(page.getByRole("dialog", { name: "New contact", exact: true })).toBeVisible();
    await page.getByLabel("Name", { exact: true }).fill("Ada Lovelace");
    await expect(page.getByLabel("Name", { exact: true })).toHaveValue("Ada Lovelace");
    await page.getByLabel("Group", { exact: true }).selectOption("work");
    await expect(page.getByLabel("Group", { exact: true })).toHaveValue("work");
    await page.getByLabel("Name", { exact: true }).press("Escape");
    await expect(page.getByRole("dialog", { name: "New contact", exact: true })).toBeHidden();
    await expect(page.getByText("Grace Hopper", { exact: true })).toBeVisible();
  });
}
